INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q41', 'railway-exam-bank', 'General Awareness', 0, 40, 'What is the full form of "RRB," and what is its role in railway recruitment?', 'RRB stands for Railway Recruitment Board — a set of regional boards under the Ministry of Railways responsible for conducting recruitment examinations (such as NTPC, Group D, ALP) for various non-gazetted posts in Indian Railways.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q42', 'railway-exam-bank', 'General Awareness', 0, 41, 'What is the significance of the "Konkan Railway," and which states does it connect?', 'The Konkan Railway is a railway line running along the western coast of India, connecting Maharashtra, Goa, and Karnataka through challenging coastal and hilly terrain, including numerous tunnels and bridges, significantly reducing travel time along the west coast compared to the earlier inland routes.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q43', 'railway-exam-bank', 'General Awareness', 0, 42, 'What does "PSU" stand for, and name one PSU under the Ministry of Railways.', 'PSU stands for Public Sector Undertaking — a government-owned corporation. Examples under the Ministry of Railways include IRCTC (Indian Railway Catering and Tourism Corporation), RVNL (Rail Vikas Nigam Limited), and CONCOR (Container Corporation of India).', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q44', 'railway-exam-bank', 'General Awareness', 0, 43, 'What is "Mission Raftaar," launched by Indian Railways?', 'Mission Raftaar is an Indian Railways initiative aimed at doubling the average speed of freight trains and increasing the average speed of superfast mail/express passenger trains by 25 km/h over a defined period, to improve overall network efficiency and reduce transit times.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q45', 'railway-exam-bank', 'General Awareness', 0, 44, 'What is the significance of the "Statue of Unity" railway station, and where is it located?', 'The Statue of Unity railway station (Kevadiya) is located in Gujarat, near the Statue of Unity monument dedicated to Sardar Vallabhbhai Patel. It was redeveloped as a major tourist-focused station with modern facilities to handle the increased footfall from visitors to the statue.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q46', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 45, 'In a reasoning series "2, 6, 12, 20, 30, ?", what is the next number and what is the pattern?', 'The next number is 42. The pattern is adding consecutive even numbers: +4, +6, +8, +10, +12 (i.e., the differences between consecutive terms increase by 2 each time: 2+4=6, 6+6=12, 12+8=20, 20+10=30, 30+12=42).', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q47', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 46, 'If "CAT" is coded as "DBU" by shifting each letter forward by one position in the alphabet, how would "DOG" be coded?', '"DOG" would be coded as "EPH" — each letter is shifted forward by one: D to E, O to P, G to H.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q48', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 47, 'In a family, if A is the son of B, and B is the sister of C, what is the relationship between A and C?', 'C is A''s maternal aunt or uncle (specifically, A''s mother''s or father''s sibling) — since B is A''s parent and B is C''s sibling, C is A''s aunt (if female) or uncle (if male) on that parent''s side.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q49', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 48, 'What is a "syllogism" in logical reasoning, and give a simple example.', 'A syllogism is a form of logical reasoning where a conclusion is drawn from two given premises (statements) assumed to be true. For example: "All mammals are animals. All dogs are mammals. Therefore, all dogs are animals" — the conclusion logically follows from the two premises.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q50', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 49, 'In a non-verbal reasoning question involving mirror images, what happens to left-right orientation when an image is reflected?', 'A mirror image reverses the left-right orientation of the object (lateral inversion) while keeping the top-bottom orientation unchanged — so text or shapes appear flipped horizontally, as if viewed through a mirror placed vertically beside the object.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q51', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 50, 'A train 150 metres long is running at a speed of 72 km/h. How long does it take to cross a stationary pole?', 'Convert speed to m/s: 72 km/h = 72 times (5/18) = 20 m/s. Time to cross a pole = distance / speed = 150 / 20 = 7.5 seconds, since the train only needs to cover its own length to pass a fixed point.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q52', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 51, 'What is the formula for calculating simple interest, and what does each term represent?', 'Simple Interest (SI) = (P times R times T) / 100, where P is the principal amount, R is the rate of interest per annum, and T is the time period in years. Unlike compound interest, simple interest is calculated only on the original principal throughout the time period.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q53', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 52, 'If the ratio of two numbers is 3:5 and their sum is 64, what are the two numbers?', 'Let the numbers be 3x and 5x. Their sum is 3x + 5x = 8x = 64, so x = 8. The numbers are 3x = 24 and 5x = 40.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q54', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 53, 'What is the formula to find the average (mean) of a set of numbers?', 'Average = (Sum of all values) / (Number of values). For example, the average of 10, 20, and 30 is (10+20+30)/3 = 60/3 = 20.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q55', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 54, 'A shopkeeper marks an item at Rs. 500 and offers a 20% discount. What is the selling price after the discount?', 'Discount amount = 20% of 500 = (20/100) times 500 = Rs. 100. Selling price = Marked price minus Discount = 500 minus 100 = Rs. 400.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q56', 'railway-exam-bank', 'General Science', 3, 55, 'What is the difference between a "physical change" and a "chemical change"? Give one example of each.', 'A physical change alters the form or appearance of a substance without changing its chemical composition (e.g., melting ice — it''s still water, just a different state). A chemical change produces a new substance with different chemical properties through a chemical reaction (e.g., burning paper, which produces ash and gases, substances different from the original paper).', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q57', 'railway-exam-bank', 'General Science', 3, 56, 'What is the function of red blood cells (erythrocytes) in the human body?', 'Red blood cells primarily transport oxygen from the lungs to body tissues and carry carbon dioxide back to the lungs for exhalation, using the protein hemoglobin, which binds to oxygen and gives blood its red color.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q58', 'railway-exam-bank', 'General Science', 3, 57, 'What is Newton''s Third Law of Motion?', 'Newton''s Third Law states that for every action, there is an equal and opposite reaction — meaning when one object exerts a force on a second object, the second object simultaneously exerts a force of equal magnitude in the opposite direction on the first object.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q59', 'railway-exam-bank', 'General Science', 3, 58, 'What is the difference between an acid and a base, in terms of pH?', 'Acids have a pH value less than 7 and release hydrogen ions (H+) in solution, tasting sour (e.g., lemon juice). Bases have a pH value greater than 7 and release hydroxide ions (OH-) in solution, often feeling slippery (e.g., soap). A pH of exactly 7 is neutral (e.g., pure water).', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q60', 'railway-exam-bank', 'General Science', 3, 59, 'What is the main function of the ozone layer in Earth''s atmosphere?', 'The ozone layer, located in the stratosphere, absorbs and blocks most of the sun''s harmful ultraviolet (UV) radiation from reaching the Earth''s surface, protecting living organisms from UV-related damage such as skin cancer and crop damage.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q16', 'police-exam-bank', 'Police Organization & Structure', 0, 15, 'What is the role of the Director General of Police (DGP) in a state?', 'The DGP is the senior-most police officer in a state, heading the state police force. The DGP is responsible for overall law and order policy, administration, discipline, and coordination across all districts and units within the state, and reports to the state government.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q17', 'police-exam-bank', 'Police Organization & Structure', 0, 16, 'What is the difference between the Central Industrial Security Force (CISF) and the Central Reserve Police Force (CRPF)?', 'CISF is primarily responsible for providing security to critical infrastructure such as airports, PSUs, nuclear installations, and government buildings. CRPF is India''s largest central armed police force, focused on internal security, counter-insurgency, anti-terrorism, and law-and-order support during elections and public events — their mandates are specialized rather than overlapping.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q18', 'police-exam-bank', 'Police Organization & Structure', 0, 17, 'What is a "Police Commissionerate system," and how does it differ from the standard district police structure?', 'Under the Commissionerate system (used in major metropolitan cities), the Police Commissioner holds both executive magisterial powers (like issuing certain orders typically reserved for a District Magistrate) and police powers, allowing faster decision-making in law-and-order situations. In the standard district system, police and magisterial powers are split between the Superintendent of Police and the District Magistrate.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q19', 'police-exam-bank', 'Police Organization & Structure', 0, 18, 'What is the role of the State Human Rights Commission in relation to police conduct?', 'The State Human Rights Commission investigates complaints of human rights violations, including those allegedly committed by police personnel, and can recommend action, compensation, or prosecution, serving as an independent oversight mechanism over police conduct within the state.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q20', 'police-exam-bank', 'Police Organization & Structure', 0, 19, 'What is "community policing," as distinguished from traditional reactive policing in terms of organizational approach?', 'Community policing restructures police priorities around building long-term partnerships with local residents to jointly identify and solve neighborhood safety issues, often involving dedicated beat officers and regular community interaction, rather than organizing solely around responding to incidents after they occur.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q21', 'police-exam-bank', 'Law & Legal Awareness', 1, 20, 'What is the difference between "bailable" and "non-bailable" offences?', 'In a bailable offence, the accused has a right to be released on bail as a matter of right, and police can grant bail. In a non-bailable offence, bail is not a matter of right — it is granted at the discretion of a court, considering factors like the severity of the crime and risk of the accused fleeing or tampering with evidence.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q22', 'police-exam-bank', 'Law & Legal Awareness', 1, 21, 'What is a "remand," and who has the authority to grant it?', 'A remand is a court order sending an arrested person into either police custody or judicial (jail) custody for further investigation, when the investigation cannot be completed within 24 hours of arrest. Only a magistrate has the authority to grant a remand.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q23', 'police-exam-bank', 'Law & Legal Awareness', 1, 22, 'What is the purpose of Section 41 of the Bharatiya Nagarik Suraksha Sanhita (BNSS), formerly Section 41 CrPC, regarding arrest without warrant?', 'This provision lays out the specific circumstances under which a police officer may arrest a person without a warrant and without the order of a magistrate — such as when a person is found committing a cognizable offence, or is a declared proclaimed offender — while also laying down safeguards requiring the officer to record reasons for the arrest.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q24', 'police-exam-bank', 'Law & Legal Awareness', 1, 23, 'What is a "zero FIR," and why was it introduced?', 'A zero FIR is an FIR that can be registered at any police station, regardless of where the offence occurred or which station normally has jurisdiction over that area. It is then transferred to the station with proper jurisdiction. It was introduced to ensure victims are not turned away or delayed due to jurisdictional disputes, especially in serious crimes like sexual assault.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q25', 'police-exam-bank', 'Law & Legal Awareness', 1, 24, 'What is "custodial violence," and what legal safeguards exist against it in India?', 'Custodial violence refers to physical or psychological abuse inflicted on a person while in police or judicial custody. Legal safeguards include constitutional protections against torture and self-incrimination (Article 20, 21), mandatory medical examination of the accused, the requirement to inform a relative/friend of the arrest, and landmark Supreme Court guidelines (such as in the D.K. Basu case) laying down mandatory procedures during arrest and detention.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q26', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 25, 'What is the significance of the Bharatiya Sakshya Adhiniyam (BSA), 2023, in relation to electronic evidence?', 'The BSA, which replaced the Indian Evidence Act, expands and modernizes the framework for admitting electronic and digital evidence in court — explicitly recognizing electronic records (emails, CCTV footage, digital documents) as primary evidence in many cases, reflecting the growing role of technology in criminal investigations.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q27', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 26, 'What is the role of the Narcotics Control Bureau (NCB) in India?', 'The NCB is the nodal agency responsible for coordinating actions against drug trafficking and enforcement of the Narcotic Drugs and Psychotropic Substances (NDPS) Act, working with state police and central agencies to combat the production, distribution, and trafficking of illegal narcotics.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q28', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 27, 'What is an "e-FIR," and what is its significance for policing?', 'An e-FIR is a First Information Report that can be filed online, without visiting a police station in person, typically for specific categories of offences like vehicle theft or lost property. It reduces the time and friction involved in reporting certain crimes and is part of broader digitization efforts in Indian policing.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q29', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 28, 'What is the purpose of the "Integrated Criminal Justice System" or ICJS?', 'ICJS is a platform that integrates databases across different pillars of the criminal justice system — police (CCTNS), forensics, prosecution, prisons, and courts — enabling real-time sharing of case-related information to speed up investigation, prosecution, and judicial processes.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q30', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 29, 'What is the significance of "CCTNS" in Indian policing?', 'CCTNS stands for Crime and Criminal Tracking Network and Systems — a nationwide networking project connecting police stations across India through a common digital platform, enabling real-time data sharing on crimes and criminals, online citizen services like FIR registration status, and improved investigation coordination across states.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q16', 'ssc-english-bank', 'English Language & Grammar', 0, 15, 'What is the difference between "who" and "whom," and when should each be used?', '"Who" is used as the subject of a verb (performing the action), e.g., "Who called you?" "Whom" is used as the object of a verb or preposition (receiving the action), e.g., "To whom did you give the book?" A simple test: if you can replace the word with "he/she," use "who"; if you can replace it with "him/her," use "whom."', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q17', 'ssc-english-bank', 'English Language & Grammar', 0, 16, 'What is a "homophone"? Give an example pair.', 'A homophone is a word that sounds the same as another word but has a different meaning and often a different spelling. For example, "their" (possessive) and "there" (location) sound identical but mean different things.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q18', 'ssc-english-bank', 'English Language & Grammar', 0, 17, 'What does "subject-verb inversion" mean, and when is it commonly used?', 'Subject-verb inversion means reversing the normal subject-verb order, placing the verb (or auxiliary verb) before the subject. It is commonly used in questions (e.g., "Is he coming?"), after negative adverbials at the start of a sentence (e.g., "Never have I seen such a thing"), and in certain conditional sentences (e.g., "Had I known, I would have come").', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q19', 'ssc-english-bank', 'English Language & Grammar', 0, 18, 'What is the difference between a "phrase" and a "clause"?', 'A phrase is a group of related words that does not contain a subject and a finite verb together, and cannot stand alone as a complete sentence (e.g., "in the morning"). A clause contains both a subject and a finite verb, and can be either independent (a complete sentence on its own) or dependent (needs to be attached to an independent clause).', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q20', 'ssc-english-bank', 'English Language & Grammar', 0, 19, 'What is the correct usage rule for "fewer" versus "less"?', '"Fewer" is used with countable nouns (things that can be counted individually), e.g., "fewer apples," "fewer people." "Less" is used with uncountable nouns (things measured as a whole, not counted individually), e.g., "less water," "less time."', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q21', 'ssc-english-bank', 'English Language & Grammar', 0, 20, 'What is a "collective noun"? Give two examples.', 'A collective noun refers to a group of people, animals, or things treated as a single unit, even though it''s made up of multiple individuals. Examples include "team" (a group of players) and "flock" (a group of birds or sheep).', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q22', 'ssc-english-bank', 'English Language & Grammar', 0, 21, 'What is the difference between "affect" and "effect" in standard usage?', '"Affect" is primarily used as a verb meaning to influence something, e.g., "The weather affected the match." "Effect" is primarily used as a noun meaning the result of an action, e.g., "The effect of the weather was a delayed match." (Effect can rarely be used as a verb meaning "to bring about," but this is less common in everyday usage.)', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q23', 'ssc-english-bank', 'English Language & Grammar', 0, 22, 'What is a "modal verb"? Give three examples.', 'A modal verb is an auxiliary verb that expresses necessity, possibility, permission, or ability, and is always followed by the base form of the main verb. Examples include "can," "must," and "should" — e.g., "You must submit the form," "She can swim."', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q24', 'ssc-english-bank', 'English Language & Grammar', 0, 23, 'What does "redundancy" mean in the context of sentence correction, and give an example.', 'Redundancy refers to the unnecessary repetition of the same idea using different words, making a sentence wordier than necessary without adding meaning. For example, "free gift" is redundant because a gift is, by definition, free — the correct phrasing is simply "gift."', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q25', 'ssc-english-bank', 'English Language & Grammar', 0, 24, 'What is the difference between "its" and "it''s"?', '"Its" (no apostrophe) is a possessive pronoun meaning "belonging to it," e.g., "The dog wagged its tail." "It''s" (with apostrophe) is a contraction of "it is" or "it has," e.g., "It''s raining today."', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q26', 'ssc-english-bank', 'English Language & Grammar', 0, 25, 'What is a "gerund," and how is it formed?', 'A gerund is a verb form ending in "-ing" that functions as a noun in a sentence. For example, in "Swimming is good exercise," "swimming" is a gerund acting as the subject of the sentence.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q27', 'ssc-english-bank', 'English Language & Grammar', 0, 26, 'What is the rule for forming the comparative and superlative of short (one-syllable) adjectives?', 'For most short adjectives, add "-er" for the comparative and "-est" for the superlative, e.g., "tall" to "taller" to "tallest." For adjectives ending in a single consonant preceded by a single vowel, the final consonant is often doubled, e.g., "big" to "bigger" to "biggest."', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q28', 'ssc-english-bank', 'English Language & Grammar', 0, 27, 'What does "antecedent" mean in grammar, and why does it matter for pronoun usage?', 'An antecedent is the noun that a pronoun refers back to in a sentence. It matters because the pronoun must agree with its antecedent in number and gender — for example, in "Riya forgot her umbrella," "Riya" is the antecedent of "her," so the pronoun correctly matches a singular, feminine subject.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q29', 'ssc-english-bank', 'English Language & Grammar', 0, 28, 'What is the difference between a "simile" and a "metaphor"?', 'A simile makes a comparison using "like" or "as" (e.g., "as brave as a lion"). A metaphor makes a direct comparison without using "like" or "as," stating that one thing IS another (e.g., "He is a lion in battle"). Both are figures of speech used to create vivid imagery.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q30', 'ssc-english-bank', 'English Language & Grammar', 0, 29, 'What is the correct order of adjectives in English when multiple adjectives describe the same noun (e.g., size, age, color)?', 'The conventional order is: Opinion, Size, Age, Shape, Color, Origin, Material, Purpose, then the Noun. For example, "a beautiful small old round red Indian wooden dining table" follows this order, though in practice most sentences use only two or three adjectives at a time.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q16', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 15, 'What is the difference between a "savings account" and a "current account"?', 'A savings account is designed for individuals to save money and earn interest on their balance, often with restrictions on the number of withdrawals per month. A current account is designed for businesses and frequent transactions, typically offering no interest but allowing unlimited transactions and overdraft facilities.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q17', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 16, 'What is "MICR," and what is its purpose on a cheque?', 'MICR stands for Magnetic Ink Character Recognition — a technology used to print a unique code (the MICR code) on cheques using special magnetic ink, allowing cheque-processing machines to quickly and accurately read and sort cheques during clearing.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q18', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 17, 'What is the purpose of the "Basel Norms" in banking regulation?', 'The Basel Norms (Basel I, II, III) are international banking regulations developed by the Basel Committee on Banking Supervision, aimed at ensuring banks maintain adequate capital reserves relative to their risk exposure, to improve the banking sector''s ability to absorb financial shocks and reduce systemic risk.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q19', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 18, 'What is a "fixed deposit (FD)," and how does it differ from a savings account?', 'A fixed deposit is a financial instrument where a lump sum of money is deposited with a bank for a fixed tenure at a predetermined, typically higher, interest rate than a savings account. Unlike a savings account, funds in an FD generally cannot be withdrawn before maturity without a penalty.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q20', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 19, 'What does "CASA ratio" mean for a bank, and why is it important?', 'CASA ratio is the proportion of a bank''s total deposits held in Current Accounts and Savings Accounts, relative to its total deposits. A higher CASA ratio is favorable for a bank because current and savings accounts typically carry little to no interest cost, improving the bank''s profitability.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q21', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 20, 'What is the role of the Securities and Exchange Board of India (SEBI)?', 'SEBI is the regulatory body for the securities and commodities market in India, responsible for protecting investor interests, regulating stock exchanges, overseeing mutual funds and brokers, and ensuring fair and transparent practices in capital markets.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q22', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 21, 'What is a "mutual fund," in simple terms?', 'A mutual fund is a pooled investment vehicle that collects money from many investors and invests it in a diversified portfolio of stocks, bonds, or other securities, managed by a professional fund manager, allowing individual investors to access diversification and professional management they might not achieve alone.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q23', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 22, 'What is the difference between "NRE" and "NRO" accounts for Non-Resident Indians (NRIs)?', 'An NRE (Non-Resident External) account holds foreign earnings converted to Indian rupees, and both the principal and interest are fully repatriable (can be transferred back abroad) and tax-free in India. An NRO (Non-Resident Ordinary) account is used to manage income earned in India (like rent or dividends), is subject to Indian income tax, and has restrictions on repatriation.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q24', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 23, 'What is "microfinance," and who does it primarily serve?', 'Microfinance refers to the provision of small loans, savings, and other financial services to low-income individuals or groups who typically lack access to traditional banking services, with the goal of promoting financial inclusion and supporting small-scale entrepreneurship, particularly in rural and underserved areas.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q25', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 24, 'What is the purpose of a "Letter of Credit (LC)" in trade finance?', 'A Letter of Credit is a financial document issued by a bank on behalf of a buyer, guaranteeing that the seller will receive payment as long as the specified terms and conditions of the trade are met. It reduces risk for both parties in international or large domestic trade transactions by having a trusted bank act as an intermediary guarantor.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q26', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 25, 'What does "base rate" mean in banking, and what replaced it in India?', 'The base rate was the minimum interest rate below which banks were not permitted to lend to customers, introduced to improve transparency in lending rates. It was later replaced by the Marginal Cost of Funds based Lending Rate (MCLR), and subsequently by the External Benchmark Lending Rate (EBLR) system, to make lending rates more responsive to changes in the RBI''s policy rates.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q27', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 26, 'What is "digital banking," and name two examples of digital banking channels.', 'Digital banking refers to the digitization of banking services, allowing customers to perform transactions and access banking services without visiting a physical branch. Examples include mobile banking apps and internet banking (net banking) portals.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q28', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 27, 'What is the significance of the "Insolvency and Bankruptcy Code (IBC), 2016"?', 'The IBC provides a unified, time-bound legal framework for resolving insolvency and bankruptcy cases for companies, partnerships, and individuals in India, aiming to maximize the value of assets, balance the interests of all stakeholders, and promote entrepreneurship and credit availability by providing a faster, more predictable resolution process than the earlier fragmented legal mechanisms.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q29', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 28, 'What is a "Systematic Investment Plan (SIP)" in mutual fund investing?', 'A SIP is an investment method where an investor contributes a fixed amount of money into a mutual fund scheme at regular intervals (e.g., monthly), rather than investing a lump sum all at once. This approach promotes disciplined investing and benefits from "rupee cost averaging," reducing the impact of market volatility over time.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q30', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 29, 'What is the difference between "monetary policy" and "fiscal policy"?', 'Monetary policy is controlled by the central bank (RBI in India) and involves managing money supply and interest rates to control inflation and stabilize the economy. Fiscal policy is controlled by the government and involves decisions about government spending and taxation to influence economic activity, employment, and growth.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q16', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 15, 'What is Erik Erikson''s theory of psychosocial development primarily concerned with?', 'Erikson''s theory proposes that individuals pass through eight stages of psychosocial development across the lifespan, each characterized by a specific conflict or crisis (e.g., "trust vs. mistrust" in infancy, "identity vs. role confusion" in adolescence) that must be resolved for healthy psychological development, influenced heavily by social relationships and experiences at each stage.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q17', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 16, 'What is "metacognition," and why is it important for learning?', 'Metacognition is the awareness and understanding of one''s own thought processes — essentially "thinking about thinking." It is important for learning because students who can monitor and regulate their own understanding (recognizing what they know and don''t know, planning strategies, evaluating their progress) tend to be more effective, self-directed learners.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q18', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 17, 'What is the difference between "intrinsic motivation" and "extrinsic motivation" in the classroom?', 'Intrinsic motivation comes from within the learner — doing something because it is inherently interesting or enjoyable (e.g., reading a book out of curiosity). Extrinsic motivation comes from external factors — doing something to earn a reward or avoid a punishment (e.g., studying to get good grades or avoid being scolded).', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q19', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 18, 'What does "individualized education" mean, and for which students is an Individualized Education Plan (IEP) typically created?', 'Individualized education means tailoring teaching methods, content, and pace to a specific student''s needs, strengths, and learning style rather than using a one-size-fits-all approach. An Individualized Education Plan (IEP) is typically created for students with identified disabilities or special educational needs, outlining specific goals, accommodations, and support services for that student.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q20', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 19, 'What is "constructivism" as a learning theory, and who are two key theorists associated with it?', 'Constructivism is a learning theory proposing that learners actively construct their own understanding and knowledge through experiences and reflection, rather than passively receiving information. Jean Piaget (focused on individual cognitive construction) and Lev Vygotsky (focused on social and cultural construction of knowledge) are two key theorists associated with constructivist approaches.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q21', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 20, 'What is the significance of "Right to Education (RTE) Act, 2009" in India?', 'The RTE Act makes free and compulsory education a fundamental right for all children aged 6 to 14 years in India, mandating that private schools reserve 25% of seats for economically weaker and disadvantaged sections, and setting minimum infrastructure and teacher qualification norms for schools.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q22', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 21, 'What is "differentiated instruction," and why do teachers use it?', 'Differentiated instruction is a teaching approach where a teacher modifies content, process, or assessment methods to meet the diverse learning needs, readiness levels, and interests of individual students within the same classroom, rather than teaching all students in exactly the same way, to ensure that all students can access and succeed in the curriculum.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q23', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 22, 'What is "Bloom''s Taxonomy," and what does it classify?', 'Bloom''s Taxonomy is a hierarchical framework classifying educational learning objectives into levels of complexity, traditionally ordered from lower to higher order thinking skills: Remember, Understand, Apply, Analyze, Evaluate, and Create. It helps teachers design lessons and assessments that target different depths of understanding, not just rote memorization.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q24', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 23, 'What is the difference between "verbal" and "non-verbal" communication in a classroom setting?', 'Verbal communication involves the use of spoken or written words to convey information (lectures, discussions, written instructions). Non-verbal communication involves body language, facial expressions, gestures, eye contact, and tone of voice, which can significantly reinforce or contradict the verbal message being delivered by a teacher.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q25', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 24, 'What is "peer learning" or "peer tutoring," and what is one benefit of this approach?', 'Peer learning involves students learning from and with each other, often through structured activities like group work or peer tutoring, where one student helps explain concepts to another. One benefit is that explaining a concept to a peer can deepen the tutor''s own understanding, while the learner may feel more comfortable asking questions of a peer than a teacher.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q26', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 25, 'What is "Attention Deficit Hyperactivity Disorder (ADHD)," and how might it affect a student''s classroom behavior?', 'ADHD is a neurodevelopmental condition characterized by persistent patterns of inattention, hyperactivity, and/or impulsivity that interfere with functioning. In the classroom, it may manifest as difficulty sustaining attention on tasks, excessive fidgeting or restlessness, and acting without thinking through consequences, requiring teachers to use structured routines and clear, consistent expectations.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q27', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 26, 'What is the role of "formative feedback" in improving student learning?', 'Formative feedback is feedback given during the learning process (rather than only at the end) that informs students about their current level of understanding and specific, actionable steps to improve — helping them correct misunderstandings and build skills progressively, rather than only learning about their performance after an assessment is already complete.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q28', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 27, 'What is "rote learning," and how does it differ from "meaningful learning"?', 'Rote learning involves memorizing information through repetition without necessarily understanding its meaning or how it connects to other knowledge (e.g., memorizing multiplication tables by repetition alone). Meaningful learning involves understanding the underlying concepts and connecting new information to existing knowledge, enabling deeper comprehension and better long-term retention and application.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q29', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 28, 'What is "continuous and comprehensive evaluation (CCE)" as an assessment approach?', 'CCE is an evaluation approach that assesses students regularly throughout the academic year (continuous) across both academic and non-academic domains such as co-curricular activities, life skills, and attitudes (comprehensive), rather than relying solely on a single final examination, aiming to reduce exam stress and provide a holistic picture of a student''s development.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q30', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 29, 'What is the significance of "home language" versus "school language" for early childhood learners, according to pedagogical research?', 'Research shows that young children learn most effectively when initial instruction occurs in their home language (mother tongue), since it builds on concepts and vocabulary they already understand, before gradually transitioning to instruction in a second or official school language — a principle reflected in NEP 2020''s emphasis on mother-tongue-based instruction in early grades.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q16', 'shared-gk-bank', 'Indian Polity', 0, 15, 'What is the role of the Comptroller and Auditor General (CAG) of India?', 'The CAG audits the accounts of the Union and State governments, as well as bodies substantially financed by government funds, ensuring transparency and accountability in public spending. The CAG''s reports are submitted to the President or Governor and then presented before the relevant legislature.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q17', 'shared-gk-bank', 'Geography', 1, 16, 'What is a "tsunami," and what commonly causes it?', 'A tsunami is a series of large ocean waves caused by the sudden displacement of a large volume of water, most commonly triggered by undersea earthquakes, but also by volcanic eruptions, underwater landslides, or meteorite impacts.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q18', 'shared-gk-bank', 'History', 2, 17, 'What was the significance of the Jallianwala Bagh massacre, and when did it occur?', 'The Jallianwala Bagh massacre occurred on April 13, 1919, in Amritsar, when British troops under General Dyer opened fire on a peaceful gathering of unarmed civilians, killing hundreds. It became a turning point in India''s independence movement, intensifying nationalist sentiment and opposition to British rule.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q19', 'shared-gk-bank', 'Economy', 3, 18, 'What is "disinvestment," in the context of Indian government policy?', 'Disinvestment refers to the government selling or liquidating its stake (ownership) in public sector undertakings (PSUs), either partially or fully, typically to raise revenue, improve efficiency through private participation, or reduce the government''s role in running commercial enterprises.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q20', 'shared-gk-bank', 'Science & Technology', 5, 19, 'What is "Chandrayaan-3," and what did it achieve?', 'Chandrayaan-3 is an Indian Space Research Organisation (ISRO) lunar mission that successfully achieved a soft landing near the Moon''s south pole on August 23, 2023, making India the fourth country to achieve a soft lunar landing and the first to land near the lunar south pole region.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q21', 'shared-gk-bank', 'Science & Technology', 5, 20, 'What is "5G" technology, and what is its main advantage over 4G?', '5G is the fifth generation of mobile network technology, offering significantly higher data transfer speeds, lower latency (response time), and the capacity to connect many more devices simultaneously compared to 4G, enabling applications like real-time remote surgery, autonomous vehicles, and large-scale IoT (Internet of Things) deployments.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q22', 'shared-gk-bank', 'Sports', 6, 21, 'Which country has won the most ICC Cricket World Cup titles (men''s) as of 2024?', 'Australia has won the most ICC Cricket World Cup titles in men''s cricket, with multiple championships across different editions of the tournament, making them the most successful team in the tournament''s history.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q23', 'shared-gk-bank', 'Sports', 6, 22, 'What is the significance of the "Khelo India" programme?', 'Khelo India is a national programme launched by the Government of India to revive and promote sports culture at the grassroots level across the country, through infrastructure development, talent identification, and scholarships for promising young athletes, aiming to build a strong sporting ecosystem from school level upward.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q24', 'shared-gk-bank', 'Awards & Honours', 7, 23, 'What is the "Bharat Ratna," and what does it recognize?', 'The Bharat Ratna is India''s highest civilian award, recognizing exceptional and distinguished service of the highest order in any field, including the arts, literature, science, and public service, awarded by the President of India on the recommendation of the Prime Minister.', '2026-11-12T14:40:43.236Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q25', 'shared-gk-bank', 'Awards & Honours', 7, 24, 'What is the "Nobel Prize," and in which fields is it awarded?', 'The Nobel Prize is an international award established by Alfred Nobel''s will, given annually in the fields of Physics, Chemistry, Physiology or Medicine, Literature, Peace, and (since 1969) Economic Sciences, recognizing individuals or organizations who have made outstanding contributions to humanity in these areas.', '2026-11-12T14:40:43.236Z');
